[
  {
    "incident": {
      "component": "kubernetes",
      "category": "disk_pressure",
      "status": "firing",
      "summary": "PVC data-loki-0 in namespace logging is 92% full with an estimated 16 hours until exhaustion."
    },
    "assessment": {
      "urgency": "medium",
      "rationale": "Time-to-exhaustion (TTE) is estimated at 16.0 hours, which is below the 72h threshold."
    },
    "facts": [
      "used_pct = 92.0%",
      "filesystem_size_bytes = 107374182400.0",
      "filesystem_available_bytes = 8589934592.0",
      "growth_rate_bytes_per_hour = 536870912.0",
      "storage_class = local-path",
      "allow_volume_expansion = False",
      "reclaim_policy = Delete",
      "namespace = logging",
      "persistentvolumeclaim = data-loki-0",
      "alertname = KubePersistentVolumeFillingUp"
    ],
    "missing_context": [
      {
        "item": "inode_free_pct",
        "why": "Disk exhaustion can be caused by inode depletion rather than byte capacity.",
        "how_to_check": "kubectl exec <pod-name> -- df -i"
      },
      {
        "item": "historical_growth_baseline",
        "why": "To determine if current growth is a spike or a steady trend (global.capacity.001).",
        "how_to_check": "PromQL: deriv(kubelet_volume_stats_used_bytes{persistentvolumeclaim='data-loki-0'}[7d])"
      }
    ],
    "immediate_actions": [
      {
        "action": "Identify top growing directories inside the pod",
        "purpose": "Locate the source of growth to determine if it can be managed via application retention (global.triage.001).",
        "conditions": "Pod must be running.",
        "expected_effect": "Identification of specific files/folders consuming space.",
        "risks": "Minimal; read-only operation.",
        "requires_approval": false,
        "verify": "Check output of du command.",
        "rule_ids": [
          "k8s.storage.004"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Check application retention settings",
        "hypothesis": "Loki retention policies (e.g., retention_period) are too long or misconfigured, causing data accumulation.",
        "how_to_check": "Inspect Loki configuration (ConfigMap or helm values) for retention settings."
      },
      {
        "step": "Analyze growth pattern",
        "hypothesis": "The growth is a sudden spike (e.g., log burst) rather than linear accumulation.",
        "how_to_check": "PromQL: predict_linear(kubelet_volume_stats_available_bytes{persistentvolumeclaim='data-loki-0'}[6h], 4*3600)"
      }
    ],
    "root_cause_hypotheses": [
      "Loki retention policy is not purging old chunks/indexes fast enough.",
      "Sudden increase in log ingestion volume causing rapid disk usage.",
      "Unintended large files (e.g., debug logs or crash dumps) being written to the volume."
    ],
    "dangerous_operations": [
      {
        "operation": "PVC Expansion",
        "why_dangerous": "The StorageClass 'local-path' has allow_volume_expansion=False. Attempting to resize may fail or require manual node-level intervention. Furthermore, expansion hides the root cause (global.capacity.001).",
        "rule_id": "k8s.storage.001"
      },
      {
        "operation": "Deleting files in data directory",
        "why_dangerous": "Deleting files within the Loki data directory can lead to index corruption or service instability (linux.storage.006).",
        "rule_id": "linux.storage.006"
      },
      {
        "operation": "Deleting PVC/PV",
        "why_dangerous": "The reclaim_policy is 'Delete'; deleting the PVC will result in permanent data loss (k8s.storage.003).",
        "rule_id": "k8s.storage.003"
      }
    ],
    "applied_expert_rules": [
      "global.capacity.001",
      "global.triage.001",
      "global.evidence.001",
      "k8s.storage.001",
      "k8s.storage.003",
      "k8s.storage.004",
      "linux.storage.004",
      "linux.storage.006"
    ],
    "incident_update": "⚠️ *Disk Pressure Alert*: PVC `data-loki-0` in `logging` is 92% full. Estimated TTE is ~16h. Investigating growth source and Loki retention settings. Note: `local-path` storage class does not support expansion."
  }
]
